/**
 * The product's own pictures, shown on its page after its chart pictures and
 * before its square cover (components/ProductPage.tsx), in the order a buyer
 * should meet them.
 *
 * 2026-10-22 - THE CHATGPT PRODUCT CARDS ARE OFF THE SITE (Tom: "remove ALL
 * product cards, the ones made by chat gpt, i will make new and updated ones,
 * more elegant and better made"). These were the 28 annotated "product guide"
 * boards (astronaut header, "Built for NinjaTrader" footer) on 15 product
 * pages: /shots/0920, /shots/1001, /shots/1004 and /shots/1006. The files and
 * the old version of this file are in "DS Archive\13 ChatGPT Product Cards
 * Removed 2026-10-22"; their masters in DS Media are untouched. A product that
 * had only boards beside its cover now shows its charts and its cover. New
 * cards go in as new entries below, under a new batch folder.
 *
 * The same day, DS Live Background and DS Time Intervals got every picture in
 * their media folders, not just the cover: DS Media\02 Products\<name>\
 * (Screenshots, the v2.1 UI renders, and Tom's 10-22 box-on-chart composite),
 * plus the DS Time Intervals chart screenshot in DS Master Folder\DS Time
 * Intervals\Media. The 4K smoke frames are served at 2560 wide, everything
 * else at its own size, all lossless except the two composites (webp q90):
 * a lossy copy erased NinjaTrader's faint grid lines from the smoke frames.
 * The two toolbar rows of each skin (1040x52 each) are shown as one picture,
 * one above the other with a clear gap, their pixels untouched - alone, each
 * would be a sliver on the 16:9 stage. Left out on purpose: the v1 screenshots
 * from before the redesign (the old gold look) and the September
 * "Screenshots\DS Time Intervals.png".
 *
 * Later on 10-22 Tom cut both galleries down (marked on a screenshot): DS Live
 * Background keeps the three smoke frames and its cover; DS Time Intervals keeps
 * the chart screenshot and the two toolbar pictures, and shows NO square cover
 * in its gallery (WITHOUT_COVER below; the cover still serves the shelf cards).
 * Out: the Properties window, both box-on-chart composites, and the Time
 * Intervals grid, custom-interval and favorites renders on both skins. Those
 * nine files went to the same archive folder, never published.
 *
 * Every picture sits whole inside the stage on the stage's own black (no
 * cropping), whatever its shape. `blur` is an inlined 16px preview painted
 * while the full file loads (PIL thumbnail -> JPEG q40 -> base64).
 *
 * A re-exported picture gets a NEW filename (one-year immutable asset cache).
 */
export type Shot = {
  src: string;
  /** Native pixel size. */
  w: number;
  h: number;
  caption: string;
  /** What the picture shows, for screen readers and search. */
  alt: string;
  blur: string;
};

